/* gfx_font.h -- TEXTOUT's fonts (data generated by tools/mkfont.py into
 * src/font/gfx_font.c). */
#ifndef PPL_GFX_FONT_H
#define PPL_GFX_FONT_H

#include <stdint.h>

typedef struct gfx_glyph {
    uint16_t off;          /* byte offset of the bitmap in the font's data */
    uint8_t adv, w, h;     /* advance (the Prime's), ink box */
    int8_t x, y;           /* ink box offset from the pen on the baseline */
} gfx_glyph;

typedef struct gfx_font {
    uint8_t size, base, cell;   /* pixel size, baseline and cell height */
    const gfx_glyph *g;         /* one per gfx_font_cp entry */
    const uint8_t *data;
} gfx_font;

extern const uint16_t gfx_font_cp[];   /* sorted code points; [0] = 0, the missing glyph */
extern const int gfx_font_ncp;
extern const gfx_font gfx_fonts[7];

#endif
